const test = require('node:test');
const assert = require('node:assert/strict');
const { EventEmitter } = require('node:events');
const { relayStatus } = require('../relay.cjs');
test('forwards positional arguments and emit return value', () => {
  const emitter = new EventEmitter();
  const received = [];
  emitter.on('shipped', (...args) => received.push(args));
  assert.equal(relayStatus(emitter, 'shipped', ['box9',3]), true);
  assert.deepEqual(received, [['box9',3]]);
  assert.equal(relayStatus(emitter, 'unobserved', ['box9']), false);
  relayStatus(emitter, 'shipped', []);
  assert.deepEqual(received[1], []);
});
test('preserves array elements and object identity', () => {
  const emitter = new EventEmitter();
  const parcel = {id:'box4'}, marks = ['fragile'];
  const args = Object.freeze([parcel,marks,undefined]);
  let seen;
  emitter.on('status', (...values) => { seen = values; });
  relayStatus(emitter, 'status', args);
  assert.equal(seen.length, 3);
  assert.strictEqual(seen[0], parcel);
  assert.strictEqual(seen[1], marks);
  assert.equal(seen[2], undefined);
});

